import React, { useState, useEffect } from "react";
import { useOutletContext } from "react-router-dom";

/**
 * Project Savings tab (TabsUI.xlsx -> Tab2)
 * Pre-Capability vs Post-Capability PD/Cost and Savings
 * Orange cells computed from light green inputs.
 */
export default function ProjectSavingsTab() {
  const { intakeNumber } = useOutletContext();
  const [form, setForm] = useState({
    // Inputs (light green)
    totalDealCount: "",      // N
    manualPerDay: "",        // N1
    autoPerDay: "",          // N2
    cycles: "",              // # cycles
    rateBase: 8,             // R1 placeholder (hrs/day equivalent)
    rateAdj: 8,              // R2 placeholder (for 15% adj like C1=PD1*8*(R1+(0.15*R2))
    // Computed (orange)
    prePD: 0,                // PD1=(N/N1)
    preCost: 0,              // C1 = PD1*8*(R1+(0.15*R2))
    postPD: 0,               // PD2=(N/N2)
    postCost: 0,             // C2 = (similar expression)
    savings: 0
  });

  const onChange = (k, v) => setForm((p) => ({ ...p, [k]: v }));

  useEffect(() => {
    const N = Number(form.totalDealCount || 0);
    const N1 = Number(form.manualPerDay || 0);
    const N2 = Number(form.autoPerDay || 0);
    const cycles = Number(form.cycles || 0);
    const R1 = Number(form.rateBase || 0);
    const R2 = Number(form.rateAdj || 0);

    const PD1 = N1 ? N / N1 : 0;
    const C1 = PD1 * 8 * (R1 + (0.15 * R2));
    const PD2 = N2 ? N / N2 : 0;
    const C2 = PD2 * 8 * (R1 + (0.15 * R2));
    const save = (C1 - C2) * Math.max(cycles, 1);

    setForm((p) => ({
      ...p,
      prePD: PD1,
      preCost: C1,
      postPD: PD2,
      postCost: C2,
      savings: save
    }));
  }, [form.totalDealCount, form.manualPerDay, form.autoPerDay, form.cycles, form.rateBase, form.rateAdj]);

  return (
    <div className="tab-wrap">
      <div className="tab-section tab-section-yellow">TDM Savings</div>

      <div className="grid-2">
        <label className="tab-label tab-label-green">Total deal count (N)</label>
        <input className="tab-input" type="number" value={form.totalDealCount} onChange={(e) => onChange("totalDealCount", e.target.value)} />

        <label className="tab-label tab-label-green">Manual deal creation per day (N1)</label>
        <input className="tab-input" type="number" value={form.manualPerDay} onChange={(e) => onChange("manualPerDay", e.target.value)} />

        <label className="tab-label tab-label-green">Average automation deal creation per day (N2)</label>
        <input className="tab-input" type="number" value={form.autoPerDay} onChange={(e) => onChange("autoPerDay", e.target.value)} />

        <label className="tab-label tab-label-green">Number of cycles</label>
        <input className="tab-input" type="number" value={form.cycles} onChange={(e) => onChange("cycles", e.target.value)} />

        <label className="tab-label tab-label-green">Rate base (R1)</label>
        <input className="tab-input" type="number" value={form.rateBase} onChange={(e) => onChange("rateBase", e.target.value)} />

        <label className="tab-label tab-label-green">Rate adjust (R2)</label>
        <input className="tab-input" type="number" value={form.rateAdj} onChange={(e) => onChange("rateAdj", e.target.value)} />
      </div>

      <div className="grid-2 mt-4">
        <label className="tab-label tab-label-orange">Pre-Capability Total PD (PD1)</label>
        <input className="tab-input tab-input-orange" value={form.prePD} disabled />

        <label className="tab-label tab-label-orange">Pre-Capability Cost (C1)</label>
        <input className="tab-input tab-input-orange" value={form.preCost} disabled />

        <label className="tab-label tab-label-orange">Post-Capability Total PD (PD2)</label>
        <input className="tab-input tab-input-orange" value={form.postPD} disabled />

        <label className="tab-label tab-label-orange">Post-Capability Cost (C2)</label>
        <input className="tab-input tab-input-orange" value={form.postCost} disabled />

        <label className="tab-label tab-label-orange">Savings</label>
        <input className="tab-input tab-input-orange" value={form.savings} disabled />
      </div>
    </div>
  );
}
